#![allow(non_snake_case, unused_imports)]

use hex_literal::hex;
use ssz::{types::*, Ssz};
use typenum::U;
use unionlabs::{hash::H256, uint::U256};

pub mod container_types {
    include!("../../tests-generator/src/container_types.rs");
}
use container_types::*;
#[test]
fn valid_BitsStruct_lengthy_0() {
    const EXPECTED_ENCODING: &[u8] = &[
        11_u8, 0_u8, 0_u8, 0_u8, 2_u8, 0_u8, 12_u8, 0_u8, 0_u8, 0_u8, 101_u8, 46_u8, 94_u8,
    ];
    const EXPECTED_ROOT: H256 = <H256>::new(hex!(
        "9c6ecf69a7358d02abee9eb030842f538e13cf10d67747887f0e536fe4eb791f"
    ));

    let expected_value: BitsStruct = BitsStruct {
        a: BitList::from_bytes([46_u8].to_vec().into()).unwrap(),
        b: BitVector::from_bytes([2_u8].to_vec().into()).unwrap(),
        c: BitVector::from_bytes([0_u8].to_vec().into()).unwrap(),
        d: BitList::from_bytes([94_u8].to_vec().into()).unwrap(),
        e: BitVector::from_bytes([101_u8].to_vec().into()).unwrap(),
    };

    assert_eq!(
        expected_value,
        <BitsStruct as Ssz>::from_ssz_bytes(EXPECTED_ENCODING).unwrap()
    );

    assert_eq!(
        EXPECTED_ENCODING,
        <BitsStruct as Ssz>::as_ssz_bytes(&expected_value)
    );

    assert_eq!(EXPECTED_ROOT, <H256>::new(expected_value.tree_hash_root()));
}
