#[test]
fn valid_BitsStruct_max_4() {
    const EXPECTED_ENCODING: &[u8] = &[
        11_u8, 0_u8, 0_u8, 0_u8, 3_u8, 1_u8, 12_u8, 0_u8, 0_u8, 0_u8, 255_u8, 31_u8, 63_u8,
    ];
    const EXPECTED_ROOT: H256 = <H256>::new(hex!(
        "9b86a73b16c1aabe418cf266c4ba7160bdd39881fa3f36196c0b8fd21c689236"
    ));

    let expected_value: BitsStruct = BitsStruct {
        a: BitList::from_bytes([31_u8].to_vec().into()).unwrap(),
        b: BitVector::from_bytes([3_u8].to_vec().into()).unwrap(),
        c: BitVector::from_bytes([1_u8].to_vec().into()).unwrap(),
        d: BitList::from_bytes([63_u8].to_vec().into()).unwrap(),
        e: BitVector::from_bytes([255_u8].to_vec().into()).unwrap(),
    };

    assert_eq!(
        expected_value,
        <BitsStruct as Ssz>::from_ssz_bytes(EXPECTED_ENCODING).unwrap()
    );

    assert_eq!(
        EXPECTED_ENCODING,
        <BitsStruct as Ssz>::as_ssz_bytes(&expected_value)
    );

    assert_eq!(EXPECTED_ROOT, <H256>::new(expected_value.tree_hash_root()));
}
