#[test]
fn valid_VarTestStruct_max_chaos_0() {
    const EXPECTED_ENCODING: &[u8] = &[255_u8, 255_u8, 7_u8, 0_u8, 0_u8, 0_u8, 255_u8];
    const EXPECTED_ROOT: H256 = <H256>::new(hex!(
        "dcbe7541bc36b70f18046e6312563a5315d439a69a088931ee0daca2fdd2440b"
    ));

    let expected_value: VarTestStruct = VarTestStruct {
        a: 65535_u16,
        b: [].to_vec().try_into().unwrap(),
        c: 255_u8,
    };

    assert_eq!(
        expected_value,
        <VarTestStruct as Ssz>::from_ssz_bytes(EXPECTED_ENCODING).unwrap()
    );

    assert_eq!(
        EXPECTED_ENCODING,
        <VarTestStruct as Ssz>::as_ssz_bytes(&expected_value)
    );

    assert_eq!(EXPECTED_ROOT, <H256>::new(expected_value.tree_hash_root()));
}
